common_elements <- function(x, y) {
  if (!is.vector(x) || !is.vector(y)) {
    stop("common_elements() requires two vectors")
  }
  if (length(x) == 0 || length(y) == 0) {
    return(x[0])
  }
  keep <- x %in% y
  result <- unique(x[keep])
  result
}

common_count <- function(x, y) {
  shared <- common_elements(x, y)
  length(shared)
}

jaccard_index <- function(x, y) {
  pool <- unique(c(x, y))
  if (length(pool) == 0) {
    return(NA_real_)
  }
  shared <- common_count(x, y)
  shared / length(pool)
}

format_vector <- function(v) {
  if (length(v) == 0) {
    empty <- paste0(class(v)[1], "(0)")
    return(empty)
  }
  items <- if (is.character(v)) paste0("'", v, "'") else format(v, trim = TRUE)
  paste0("c(", paste(items, collapse = ", "), ")")
}

describe_pair <- function(x, y) {
  shared <- common_elements(x, y)
  overlap <- jaccard_index(x, y)
  ratio <- if (is.na(overlap)) "n/a" else sprintf("%.2f", overlap)
  sprintf(
    "%s & %s -> %s  (%d shared, jaccard %s)",
    format_vector(x), format_vector(y), format_vector(shared),
    length(shared), ratio
  )
}

report <- function(pairs) {
  lines <- vapply(pairs, function(p) describe_pair(p[[1]], p[[2]]), character(1))
  cat(lines, sep = "\n")
  cat("\n")
  invisible(lines)
}

main <- function() {
  numeric_pair <- list(c(1, 2, 3), c(2, 3, 4))
  letter_pair <- list(c("a", "b"), c("c", "d"))
  repeats <- list(c(5, 5, 6, 7, 7), c(7, 5, 9))
  empty_pair <- list(integer(0), c(1L, 2L))
  logical_pair <- list(c(TRUE, FALSE), c(TRUE, TRUE))
  cases <- list(numeric_pair, letter_pair, repeats, empty_pair, logical_pair)
  report(cases)
}

main()

