is_prime <- function(n) {
  if (n <= 1) {
    return(FALSE)
  }
  if (n == 2) {
    return(TRUE)
  }
  if (n %% 2 == 0) {
    return(FALSE)
  }

  limit <- floor(sqrt(n))
  i <- 3
  while (i <= limit) {
    remainder <- n %% i
    if (remainder == 0) {
      return(FALSE)
    }
    i <- i + 2
  }

  result <- TRUE
  return(result)
}

# Example usage:
prime_test_1 <- 7
is_prime_1_result <- is_prime(prime_test_1)
print(paste(prime_test_1, "is prime:", is_prime_1_result))

prime_test_2 <- 9
is_prime_2_result <- is_prime(prime_test_2)
print(paste(prime_test_2, "is prime:", is_prime_2_result))

prime_test_3 <- 2
is_prime_3_result <- is_prime(prime_test_3)
print(paste(prime_test_3, "is prime:", is_prime_3_result))

prime_test_4 <- 1
is_prime_4_result <- is_prime(prime_test_4)
print(paste(prime_test_4, "is prime:", is_prime_4_result))

prime_test_5 <- 29
is_prime_5_result <- is_prime(prime_test_5)
print(paste(prime_test_5, "is prime:", is_prime_5_result))

