coin_flip <- function() {
  faces <- c("Heads", "Tails")
  idx <- sample.int(2L, size = 1L)
  faces[idx]
}

flip_sequence <- function(n) {
  if (!is.numeric(n) || length(n) != 1L || is.na(n) || n < 1) {
    stop("n must be a single positive number of flips")
  }
  count <- as.integer(n)
  results <- character(count)
  for (i in seq_len(count)) {
    results[i] <- coin_flip()
  }
  results
}

tally_flips <- function(results) {
  heads <- sum(results == "Heads")
  tails <- sum(results == "Tails")
  list(heads = heads, tails = tails, total = heads + tails)
}

longest_run <- function(results) {
  best <- 0L
  current <- 0L
  previous <- ""
  for (face in results) {
    if (identical(face, previous)) {
      current <- current + 1L
    } else {
      current <- 1L
      previous <- face
    }
    if (current > best) {
      best <- current
    }
  }
  best
}

format_report <- function(results) {
  counts <- tally_flips(results)
  share <- counts$heads / counts$total * 100
  header <- sprintf("Flips: %d", counts$total)
  body <- sprintf("Heads: %d (%.1f%%)   Tails: %d (%.1f%%)",
                  counts$heads, share, counts$tails, 100 - share)
  streak <- sprintf("Longest identical run: %d", longest_run(results))
  paste(header, body, streak, sep = "\n")
}

main <- function() {
  single <- coin_flip()
  cat("A single flip:", single, "\n")

  second <- coin_flip()
  cat("Another flip:", second, "\n\n")

  trial <- flip_sequence(20L)
  cat("Twenty flips:\n")
  cat(paste(trial, collapse = " "), "\n")
  cat(format_report(trial), "\n\n")

  big <- flip_sequence(10000L)
  cat("Ten thousand flips:\n")
  cat(format_report(big), "\n")
}

main()

