get_keys <- function(dict) {
  if (!is.vector(dict)) {
    stop("get_keys expects a named vector")
  }
  keys <- names(dict)
  if (is.null(keys)) {
    return(character(0))
  }
  as.character(keys)
}

has_key <- function(dict, key) {
  keys <- get_keys(dict)
  key %in% keys
}

get_value <- function(dict, key, default = NA) {
  keys <- get_keys(dict)
  position <- match(key, keys)
  if (is.na(position)) {
    return(default)
  }
  unname(dict[[position]])
}

missing_keys <- function(dict, required) {
  present <- get_keys(dict)
  setdiff(required, present)
}

describe_dict <- function(dict, label) {
  keys <- get_keys(dict)
  if (length(keys) == 0) {
    return(paste0(label, ": <no keys>"))
  }
  entries <- vapply(keys, function(k) paste0(k, "=", get_value(dict, k)), character(1))
  joined <- paste(entries, collapse = ", ")
  paste0(label, " [", length(keys), " keys]: ", joined)
}

validate_record <- function(dict, required) {
  gaps <- missing_keys(dict, required)
  if (length(gaps) == 0) {
    return("complete")
  }
  paste("missing:", paste(gaps, collapse = "/"))
}

main <- function() {
  person <- c(name = "Alice", age = 30)
  place <- c(city = "NY")
  anonymous <- c("x", "y")
  required <- c("name", "age", "city")

  records <- list(person = person, place = place, anonymous = anonymous)
  for (label in names(records)) {
    entry <- records[[label]]
    cat(describe_dict(entry, label), "\n")
    cat("  keys:", paste(get_keys(entry), collapse = ", "), "\n")
    cat("  validation:", validate_record(entry, required), "\n")
  }

  lookup <- get_value(person, "age")
  cat("age of person:", lookup, "\n")
  flag <- has_key(place, "city")
  cat("place has city:", flag, "\n")
}

main()

