round_to_integer <- function(x) {
  validated <- validate_numeric(x)
  rounded <- round(validated)
  storage.mode(rounded) <- "integer"
  rounded
}

validate_numeric <- function(x) {
  if (is.null(x)) {
    stop("round_to_integer: input must not be NULL")
  }
  if (is.logical(x) && all(is.na(x))) {
    x <- as.numeric(x)
  }
  if (!is.numeric(x)) {
    offending <- class(x)[1]
    stop(sprintf("round_to_integer: expected a numeric vector, got '%s'", offending))
  }
  infinite <- is.infinite(x)
  if (any(infinite)) {
    positions <- paste(which(infinite), collapse = ", ")
    stop(sprintf("round_to_integer: infinite value(s) at position(s) %s", positions))
  }
  x
}

rounding_delta <- function(x) {
  rounded <- round_to_integer(x)
  as.numeric(rounded) - x
}

format_rounding <- function(x) {
  rounded <- round_to_integer(x)
  delta <- rounding_delta(x)
  labels <- ifelse(delta > 0, "up", ifelse(delta < 0, "down", "exact"))
  entries <- sprintf("%8.3f -> %5d  (%s)", x, rounded, labels)
  paste(entries, collapse = "\n")
}

rounding_summary <- function(x) {
  delta <- rounding_delta(x)
  up <- sum(delta > 0, na.rm = TRUE)
  down <- sum(delta < 0, na.rm = TRUE)
  exact <- sum(delta == 0, na.rm = TRUE)
  total <- sum(abs(delta), na.rm = TRUE)
  sprintf("rounded up: %d, rounded down: %d, unchanged: %d, total shift: %.3f",
          up, down, exact, total)
}

main <- function() {
  cases <- list(
    c(2.3, 2.7, 2.5),
    c(-1.2, -1.8),
    c(0, 0.5, 1.5, -0.5, -2.5),
    c(10.04, 99.96, 1234.5)
  )
  for (values in cases) {
    header <- paste0("input: c(", paste(values, collapse = ", "), ")")
    cat(header, "\n", sep = "")
    cat(format_rounding(values), "\n", sep = "")
    cat(rounding_summary(values), "\n\n", sep = "")
  }
  bad <- try(round_to_integer(c("1.5", "2.5")), silent = TRUE)
  if (inherits(bad, "try-error")) {
    reason <- conditionMessage(attr(bad, "condition"))
    cat("caught: ", reason, "\n", sep = "")
  }
  invisible(NULL)
}

main()

