validate_args <- function(main_string, target_substring, replacement_substring) {
  args <- list(main = main_string, target = target_substring, replacement = replacement_substring)
  for (name in names(args)) {
    value <- args[[name]]
    if (!is.character(value) || length(value) != 1L || is.na(value)) {
      stop(sprintf("'%s' must be a single non-NA character string", name))
    }
  }
  if (!nzchar(target_substring)) {
    stop("'target' must not be the empty string")
  }
  invisible(TRUE)
}

find_occurrences <- function(main_string, target_substring) {
  span <- nchar(target_substring)
  limit <- nchar(main_string) - span + 1L
  positions <- integer(0)
  index <- 1L
  while (index <= limit) {
    candidate <- substr(main_string, index, index + span - 1L)
    if (identical(candidate, target_substring)) {
      positions <- c(positions, index)
      index <- index + span
    } else {
      index <- index + 1L
    }
  }
  positions
}

replace_substring <- function(main_string, target_substring, replacement_substring) {
  validate_args(main_string, target_substring, replacement_substring)
  positions <- find_occurrences(main_string, target_substring)
  if (length(positions) == 0L) {
    return(main_string)
  }
  span <- nchar(target_substring)
  pieces <- character(0)
  cursor <- 1L
  for (start in positions) {
    if (start > cursor) {
      pieces <- c(pieces, substr(main_string, cursor, start - 1L))
    }
    pieces <- c(pieces, replacement_substring)
    cursor <- start + span
  }
  total <- nchar(main_string)
  if (cursor <= total) {
    pieces <- c(pieces, substr(main_string, cursor, total))
  }
  paste(pieces, collapse = "")
}

report_replacement <- function(main_string, target_substring, replacement_substring) {
  result <- replace_substring(main_string, target_substring, replacement_substring)
  hits <- length(find_occurrences(main_string, target_substring))
  sprintf("'%s' [%s -> %s] => '%s' (%d replacement(s))",
          main_string, target_substring, replacement_substring, result, hits)
}

main <- function() {
  cases <- list(
    list("hello world", "world", "there"),
    list("banana", "a", "o"),
    list("aaaa", "aa", "b"),
    list("nothing here", "xyz", "abc"),
    list("remove me please", "me ", "")
  )
  for (case in cases) {
    line <- report_replacement(case[[1]], case[[2]], case[[3]])
    cat(line, "\n", sep = "")
  }
}

main()

