all_unique <- function(x) {
  if (length(x) == 0) {
    return(TRUE)
  }
  seen <- unique(x)
  length(seen) == length(x)
}

duplicated_values <- function(x) {
  repeats <- x[duplicated(x)]
  unique(repeats)
}

describe_vector <- function(x, label) {
  unique_flag <- all_unique(x)
  contents <- paste(format(x, trim = TRUE), collapse = ", ")
  header <- sprintf("%s: [%s]", label, contents)
  if (unique_flag) {
    verdict <- "all elements unique"
  } else {
    dups <- duplicated_values(x)
    verdict <- sprintf("repeated: %s", paste(dups, collapse = ", "))
  }
  sprintf("%s -> %s (%s)", header, unique_flag, verdict)
}

first_duplicate_position <- function(x) {
  flags <- duplicated(x)
  if (any(flags)) {
    which(flags)[1]
  } else {
    NA_integer_
  }
}

summarise_cases <- function(cases) {
  labels <- names(cases)
  if (is.null(labels)) {
    labels <- paste0("case", seq_along(cases))
  }
  lines <- character(length(cases))
  for (i in seq_along(cases)) {
    vec <- cases[[i]]
    lines[i] <- describe_vector(vec, labels[i])
    pos <- first_duplicate_position(vec)
    if (!is.na(pos)) {
      lines[i] <- paste0(lines[i], sprintf(" first repeat at index %d", pos))
    }
  }
  lines
}

main <- function() {
  cases <- list(
    ascending = c(1, 2, 3),
    with_repeat = c(1, 2, 2),
    empty = numeric(0),
    words = c("apple", "pear", "apple", "plum"),
    logicals = c(TRUE, FALSE)
  )
  report <- summarise_cases(cases)
  cat(report, sep = "\n")
  cat("\n")
  unique_count <- sum(vapply(cases, all_unique, logical(1)))
  cat(sprintf("%d of %d vectors contain only unique elements\n",
              unique_count, length(cases)))
}

main()

