nth_smallest <- function(vec, n) {
  validate_selection(vec, n)
  quickselect(as.numeric(vec), as.integer(n))
}

validate_selection <- function(vec, n) {
  if (!is.numeric(vec) || length(vec) == 0L) {
    stop("'vec' must be a non-empty numeric vector")
  }
  if (length(n) != 1L || is.na(n) || n != as.integer(n)) {
    stop("'n' must be a single whole number")
  }
  if (n < 1L || n > length(vec)) {
    stop("'n' must satisfy 1 <= n <= length(vec)")
  }
  invisible(TRUE)
}

quickselect <- function(values, k) {
  while (TRUE) {
    if (length(values) == 1L) {
      return(values[1L])
    }
    pivot <- values[length(values) %/% 2L + 1L]
    lower <- values[values < pivot]
    equal <- values[values == pivot]
    upper <- values[values > pivot]
    if (k <= length(lower)) {
      values <- lower
    } else if (k <= length(lower) + length(equal)) {
      return(pivot)
    } else {
      k <- k - length(lower) - length(equal)
      values <- upper
    }
  }
}

order_statistics <- function(vec, ranks) {
  vapply(ranks, function(r) nth_smallest(vec, r), numeric(1L))
}

format_rank <- function(n) {
  suffix <- if (n %% 100L %in% 11:13) {
    "th"
  } else {
    switch(as.character(n %% 10L), "1" = "st", "2" = "nd", "3" = "rd", "th")
  }
  paste0(n, suffix)
}

report_selection <- function(vec, ranks) {
  stats <- order_statistics(vec, ranks)
  labels <- vapply(ranks, format_rank, character(1L))
  lines <- sprintf("%s smallest of [%s] is %s",
                   labels, paste(vec, collapse = ", "), format(stats))
  cat(lines, sep = "\n")
  cat("\n")
  invisible(stats)
}

main <- function() {
  sample_a <- c(5, 2, 8, 1)
  sample_b <- c(10, 3, 7)
  report_selection(sample_a, seq_along(sample_a))
  report_selection(sample_b, 1L)
  spread <- nth_smallest(sample_a, length(sample_a)) - nth_smallest(sample_a, 1L)
  cat("Range of first sample:", spread, "\n")
}

main()

