count_frequency <- function(x) {
  if (is.null(x) || length(x) == 0) {
    return(integer(0))
  }
  keys <- as.character(x)
  uniq <- unique(keys)
  counts <- integer(length(uniq))
  names(counts) <- uniq
  for (k in keys) {
    counts[[k]] <- counts[[k]] + 1L
  }
  counts
}

most_common <- function(freq, n = 1) {
  if (length(freq) == 0) {
    return(integer(0))
  }
  ordered <- freq[order(-freq, names(freq))]
  top <- min(n, length(ordered))
  ordered[seq_len(top)]
}

relative_frequency <- function(freq) {
  total <- sum(freq)
  if (total == 0) {
    return(numeric(0))
  }
  freq / total
}

format_report <- function(freq, title) {
  header <- paste0(title, " (", sum(freq), " items, ", length(freq), " distinct)")
  if (length(freq) == 0) {
    return(paste0(header, "\n  <empty>"))
  }
  shares <- relative_frequency(freq)
  width <- max(nchar(names(freq)))
  lines <- character(length(freq))
  for (i in seq_along(freq)) {
    label <- formatC(names(freq)[i], width = width, flag = "-")
    pct <- formatC(100 * shares[[i]], format = "f", digits = 1, width = 5)
    bar <- strrep("#", freq[[i]])
    lines[i] <- paste0("  ", label, " : ", freq[[i]], "  ", pct, "%  ", bar)
  }
  paste(c(header, lines), collapse = "\n")
}

main <- function() {
  letters_in <- c('a', 'b', 'a', 'c')
  numbers_in <- c(1, 2, 1, 3, 2)
  words <- strsplit("the quick brown fox jumps over the lazy dog the fox", " ")[[1]]

  letter_freq <- count_frequency(letters_in)
  number_freq <- count_frequency(numbers_in)
  word_freq <- count_frequency(words)

  cat(format_report(letter_freq, "Letters"), "\n")
  cat(format_report(number_freq, "Numbers"), "\n")
  cat(format_report(word_freq, "Words"), "\n")

  leaders <- most_common(word_freq, 3)
  summary_line <- paste(names(leaders), unname(leaders), sep = "=", collapse = ", ")
  cat("Top words:", summary_line, "\n")

  stopifnot(identical(letter_freq, c(a = 2L, b = 1L, c = 1L)))
  stopifnot(identical(number_freq, c('1' = 2L, '2' = 2L, '3' = 1L)))
}

main()

