is_leap_year <- function(year) {
  (year %% 4 == 0 && year %% 100 != 0) || year %% 400 == 0
}

days_in_month <- function(year, month) {
  month_days <- c(31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
  count <- month_days[month]
  if (month == 2 && is_leap_year(year)) {
    count <- 29
  }
  count
}

parse_date <- function(text) {
  if (!grepl("^[0-9]{4}-[0-9]{2}-[0-9]{2}$", text)) {
    stop(sprintf("invalid date format: '%s' (expected YYYY-MM-DD)", text))
  }
  parts <- as.integer(strsplit(text, "-", fixed = TRUE)[[1]])
  year <- parts[1]
  month <- parts[2]
  day <- parts[3]
  if (month < 1 || month > 12) {
    stop(sprintf("invalid month in '%s'", text))
  }
  if (day < 1 || day > days_in_month(year, month)) {
    stop(sprintf("invalid day in '%s'", text))
  }
  list(year = year, month = month, day = day)
}

to_day_number <- function(parts) {
  y <- parts$year
  m <- parts$month
  if (m <= 2) {
    y <- y - 1
    m <- m + 12
  }
  era <- y %/% 100
  total <- 365 * y + y %/% 4 - era + era %/% 4
  total + (306 * (m + 1)) %/% 10 + parts$day
}

days_between <- function(date1, date2) {
  first <- parse_date(date1)
  second <- parse_date(date2)
  abs(to_day_number(second) - to_day_number(first))
}

report_span <- function(date1, date2) {
  gap <- days_between(date1, date2)
  unit <- if (gap == 1) "day" else "days"
  sprintf("%s to %s: %d %s", date1, date2, gap, unit)
}

main <- function() {
  samples <- list(
    c("2023-01-01", "2023-01-05"),
    c("2023-01-05", "2023-01-01"),
    c("2020-02-28", "2020-03-01"),
    c("2019-02-28", "2019-03-01"),
    c("2000-01-01", "2024-01-01"),
    c("2023-06-15", "2023-06-15")
  )
  for (pair in samples) {
    line <- report_span(pair[1], pair[2])
    cat(line, "\n", sep = "")
  }
}

main()

