reverse_words <- function(sentence) {
  if (!is.character(sentence) || length(sentence) != 1L) {
    stop("reverse_words expects a single character string")
  }
  if (is.na(sentence)) {
    return(NA_character_)
  }
  words <- strsplit(sentence, " ", fixed = TRUE)[[1]]
  if (length(words) == 0L) {
    return("")
  }
  reordered <- rev(words)
  paste(reordered, collapse = " ")
}

normalise_spacing <- function(sentence) {
  trimmed <- gsub("^\\s+|\\s+$", "", sentence)
  gsub("\\s+", " ", trimmed)
}

reverse_words_safely <- function(sentence) {
  cleaned <- normalise_spacing(sentence)
  reverse_words(cleaned)
}

word_count <- function(sentence) {
  cleaned <- normalise_spacing(sentence)
  if (nchar(cleaned) == 0L) {
    return(0L)
  }
  pieces <- strsplit(cleaned, " ", fixed = TRUE)[[1]]
  length(pieces)
}

format_report <- function(sentence) {
  reversed <- reverse_words_safely(sentence)
  n <- word_count(sentence)
  label <- if (n == 1L) "word" else "words"
  sprintf("%-28s -> %-28s (%d %s)", sentence, reversed, n, label)
}

report_all <- function(sentences) {
  lines <- vapply(sentences, format_report, character(1), USE.NAMES = FALSE)
  paste(lines, collapse = "\n")
}

main <- function() {
  samples <- c(
    "hello world",
    "one two three",
    "the quick brown fox jumps",
    "solo",
    "  padded   input   here  "
  )
  output <- report_all(samples)
  cat(output, "\n", sep = "")

  palindromic <- Filter(function(s) reverse_words_safely(s) == normalise_spacing(s), samples)
  summary_line <- if (length(palindromic) == 0L) {
    "no sentence reads the same with its words reversed"
  } else {
    paste("unchanged when reversed:", paste(palindromic, collapse = "; "))
  }
  cat(summary_line, "\n", sep = "")
}

main()

