  flags = report_concatenation(c(TRUE, FALSE), logical(0))

  grown = concatenate_all(list(numbers, c(5, 6), c(7)))
  cat("chained numeric:", format_vector(grown), "\n")
  cat("letters length:", length(letters_out), "\n")
  cat("flags preserved:", format_vector(flags), "\n")

  mismatch = tryCatch(concatenate_vectors(c(1, 2), c("a")),
