arithmetic_sequence <- function(start, diff, count) {
  if (!is.numeric(start) || length(start) != 1L) {
    stop("'start' must be a single numeric value")
  }
  if (!is.numeric(diff) || length(diff) != 1L) {
    stop("'diff' must be a single numeric value")
  }
  if (!is.numeric(count) || length(count) != 1L || is.na(count)) {
    stop("'count' must be a single numeric value")
  }
  if (count != as.integer(count) || count < 0L) {
    stop("'count' must be a non-negative whole number")
  }
  n <- as.integer(count)
  if (n == 0L) {
    return(numeric(0))
  }
  offsets <- seq.int(from = 0L, length.out = n)
  start + diff * offsets
}

sequence_sum <- function(start, diff, count) {
  terms <- arithmetic_sequence(start, diff, count)
  sum(terms)
}

nth_term <- function(start, diff, n) {
  if (!is.numeric(n) || length(n) != 1L || n < 1L || n != as.integer(n)) {
    stop("'n' must be a positive whole number")
  }
  index <- as.integer(n)
  terms <- arithmetic_sequence(start, diff, index)
  terms[index]
}

format_sequence <- function(terms) {
  if (length(terms) == 0L) {
    return("<empty sequence>")
  }
  pieces <- format(terms, trim = TRUE)
  paste(pieces, collapse = ", ")
}

describe_sequence <- function(start, diff, count) {
  terms <- arithmetic_sequence(start, diff, count)
  body <- format_sequence(terms)
  total <- sum(terms)
  direction <- if (diff > 0) "increasing" else if (diff < 0) "decreasing" else "constant"
  sprintf("%s (%s, sum = %s)", body, direction, format(total, trim = TRUE))
}

main <- function() {
  cases <- list(
    list(start = 1, diff = 2, count = 5),
    list(start = 10, diff = -1, count = 3),
    list(start = 2.5, diff = 0.5, count = 4),
    list(start = 7, diff = 0, count = 3),
    list(start = 0, diff = 3, count = 0)
  )
  for (case in cases) {
    label <- sprintf("arithmetic_sequence(%s, %s, %s)", case$start, case$diff, case$count)
    text <- describe_sequence(case$start, case$diff, case$count)
    cat(label, "->", text, "\n")
  }
  twelfth <- nth_term(1, 2, 12)
  cat("12th term of 1, 3, 5, ... is", twelfth, "\n")
  first_hundred <- sequence_sum(1, 1, 100)
  cat("Sum of 1..100 is", first_hundred, "\n")
  invisible(NULL)
}

main()

