check_inventory <- function(inventory, product_name) {
  if (length(inventory) == 0 || is.null(names(inventory))) {
    return(0)
  }
  matches <- which(names(inventory) == product_name)
  if (length(matches) == 0) {
    return(0)
  }
  quantity <- inventory[[matches[1]]]
  quantity
}

restock <- function(inventory, product_name, amount) {
  current <- check_inventory(inventory, product_name)
  inventory[product_name] <- current + amount
  inventory
}

fulfill_order <- function(inventory, product_name, amount) {
  available <- check_inventory(inventory, product_name)
  shipped <- min(available, amount)
  if (shipped > 0) {
    inventory[product_name] <- available - shipped
  }
  list(inventory = inventory, shipped = shipped, backordered = amount - shipped)
}

low_stock <- function(inventory, threshold) {
  keep <- inventory < threshold
  sort(inventory[keep])
}

format_report <- function(inventory) {
  if (length(inventory) == 0) {
    return("(empty inventory)")
  }
  sorted <- inventory[order(names(inventory))]
  labels <- format(names(sorted), width = max(nchar(names(sorted))))
  amounts <- formatC(as.integer(sorted), width = 5)
  paste(labels, amounts, collapse = "\n")
}

main <- function() {
  stock <- c(apple = 10, banana = 5, cherry = 2)

  cat("apple :", check_inventory(stock, "apple"), "\n")
  cat("orange:", check_inventory(stock, "orange"), "\n")

  stock <- restock(stock, "orange", 12)
  stock <- restock(stock, "banana", 3)

  shipment <- fulfill_order(stock, "cherry", 5)
  stock <- shipment$inventory
  cat("shipped", shipment$shipped, "cherry,", shipment$backordered, "backordered\n")

  scarce <- low_stock(stock, 8)
  if (length(scarce) > 0) {
    scarce_names <- paste(names(scarce), collapse = ", ")
    cat("low stock:", scarce_names, "\n")
  }

  cat(format_report(stock), "\n", sep = "")
  cat("total units:", sum(stock), "\n")
}

main()

