filter_df_by_type <- function(df, type_name) {
  if (!is.data.frame(df)) {
    stop("`df` must be a data frame")
  }
  if (!is.character(type_name) || length(type_name) != 1L) {
    stop("`type_name` must be a single string")
  }
  wanted <- tolower(type_name)
  matches <- vapply(df, column_matches_type, logical(1), wanted = wanted)
  df[, matches, drop = FALSE]
}

column_matches_type <- function(column, wanted) {
  actual <- column_type_name(column)
  if (identical(actual, wanted)) {
    return(TRUE)
  }
  if (wanted == "numeric") {
    return(actual %in% c("integer", "double"))
  }
  if (wanted == "double") {
    return(actual == "numeric")
  }
  FALSE
}

column_type_name <- function(column) {
  if (is.factor(column)) {
    return("factor")
  }
  base <- class(column)[1]
  if (base == "integer" || base == "numeric") {
    base
  } else {
    tolower(base)
  }
}

type_report <- function(df) {
  types <- vapply(df, column_type_name, character(1))
  report <- data.frame(
    column = names(df),
    type = unname(types),
    stringsAsFactors = FALSE
  )
  report[order(report$type, report$column), , drop = FALSE]
}

describe_selection <- function(df, type_name) {
  selected <- filter_df_by_type(df, type_name)
  label <- if (ncol(selected) == 0L) "<none>" else paste(names(selected), collapse = ", ")
  sprintf("%-10s -> %s", type_name, label)
}

main <- function() {
  df <- data.frame(
    a = 1,
    b = "x",
    c = TRUE,
    d = 2L,
    e = factor("lvl"),
    stringsAsFactors = FALSE
  )
  print(type_report(df))
  wanted_types <- c("numeric", "character", "logical", "integer", "factor", "complex")
  summaries <- vapply(wanted_types, function(t) describe_selection(df, t), character(1))
  cat(summaries, sep = "\n")
  cat("\n")
  numeric_only <- filter_df_by_type(df, "numeric")
  cat("numeric columns kept:", ncol(numeric_only), "\n")
  print(numeric_only)
}

main()

