is_vector_sorted <- function(vec, decreasing = FALSE) {

  len_vec <- length(vec)
  if (len_vec <= 1) {
    return(TRUE)
  }

  is_sorted <- TRUE
  if (decreasing) {
    for (i in 1:(len_vec - 1)) {
      if (vec[i] < vec[i+1]) {
        is_sorted <- FALSE
        break
      }
    }
  } else {
    for (i in 1:(len_vec - 1)) {
      if (vec[i] > vec[i+1]) {
        is_sorted <- FALSE
        break
      }
    }
  }

  result_value <- is_sorted
  return(result_value)
}

