    stop("`target_value` must be a single value")
  }
  matches = !is.na(nv) & nv == target_value
  found = keys[matches]
  found[nzchar(found)]
}

invert_mapping = function(nv) {
  values = unique(as.character(nv))
  inverted = lapply(values, function(v) get_keys_by_value(nv, v))
  names(inverted) = values
  inverted
}

count_by_value = function(nv) {
  groups = invert_mapping(nv)
  vapply(groups, length, integer(1))
}

format_lookup = function(nv, target_value) {
  keys = get_keys_by_value(nv, target_value)
  label = paste0("value ", deparse(target_value), ": ")
  if (length(keys) == 0) {
    return(paste0(label, "<no keys>"))
  }
  paste0(label, paste(keys, collapse = ", "))
}

format_report = function(nv) {
  tally = count_by_value(nv)
  ordered = tally[order(-tally, names(tally))]
  lines = character(0)
  for (value in names(ordered)) {
    entry = paste0("  ", value, " -> ", ordered[[value]], " key(s)")
    lines = c(lines, entry)
  }
  lines
}

main = function() {
  numbers = c(a = 1, b = 2, c = 1)
  colours = c(x = "red", y = "blue", z = "red")

  cat(format_lookup(numbers, 1), "\n")
  cat(format_lookup(colours, "green"), "\n")
  cat(format_lookup(colours, "red"), "\n")

  cat("Numeric tally:\n")
  cat(format_report(numbers), sep = "\n")
  cat("\nColour tally:\n")
  cat(format_report(colours), sep = "\n")
  cat("\n")

  empty = c(a = 1)[0]
  cat("Empty vector yields", length(get_keys_by_value(empty, 1)), "keys\n")
}

main()

