  drawn <- simulate_card_draw(deck, num_players * cards_each)
  splitter <- rep(seq_len(num_players), each = cards_each)
  hands <- split(drawn, splitter)
  names(hands) <- paste("Player", seq_len(num_players))
  hands
}

