    cards <- table_hands[[player]]
    cat(sprintf("%-9s %s  (%s)\n", player,
                paste(cards, collapse = " "), describe_hand(cards)))
  }

  single <- simulate_card_draw(c("A", "B", "C"), 1)
  cat("\nSingle draw from a tiny deck:", single, "\n")
}

