weighted_average <- function(values, weights) {
  if (!is.numeric(values) || !is.numeric(weights)) {
    stop("both 'values' and 'weights' must be numeric vectors")
  }
  if (length(values) != length(weights)) {
    stop("'values' and 'weights' must have the same length")
  }
  if (length(values) == 0L) {
    stop("'values' must contain at least one element")
  }
  if (anyNA(values) || anyNA(weights)) {
    stop("missing values are not supported")
  }
  total_weight <- sum(weights)
  if (total_weight == 0) {
    stop("the sum of 'weights' must not be zero")
  }
  products <- values * weights
  sum(products) / total_weight
}

normalise_weights <- function(weights) {
  total <- sum(weights)
  weights / total
}

weighted_variance <- function(values, weights) {
  centre <- weighted_average(values, weights)
  deviations <- (values - centre)^2
  weighted_average(deviations, weights)
}

describe_series <- function(label, values, weights) {
  shares <- normalise_weights(weights)
  average <- weighted_average(values, weights)
  spread <- sqrt(weighted_variance(values, weights))
  dominant <- values[which.max(shares)]
  list(
    label = label,
    average = average,
    spread = spread,
    dominant = dominant,
    shares = shares
  )
}

format_report <- function(summary) {
  share_text <- paste(sprintf("%.1f%%", 100 * summary$shares), collapse = ", ")
  lines <- c(
    sprintf("%s", summary$label),
    sprintf("  weighted average : %.5f", summary$average),
    sprintf("  weighted sd      : %.5f", summary$spread),
    sprintf("  heaviest value   : %g", summary$dominant),
    sprintf("  weight shares    : %s", share_text)
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  simple <- describe_series("Counts with rising weights", c(10, 20, 30), c(1, 2, 3))
  halves <- describe_series("Two equally weighted readings", c(5, 10), c(0.5, 0.5))
  grades <- describe_series("Course grades", c(88, 92, 75, 96), c(0.2, 0.3, 0.1, 0.4))
  reports <- vapply(list(simple, halves, grades), format_report, character(1))
  cat(paste(reports, collapse = "\n\n"), "\n", sep = "")
  invisible(reports)
}

main()

