hamming_distance <- function(a, b) {
  if (!is.character(a) || !is.character(b) || length(a) != 1L || length(b) != 1L) {
    stop("hamming_distance expects two single strings")
  }
  first <- strsplit(a, "", fixed = TRUE)[[1]]
  second <- strsplit(b, "", fixed = TRUE)[[1]]
  if (length(first) != length(second)) {
    stop("hamming_distance requires strings of equal length")
  }
  sum(first != second)
}

mismatch_positions <- function(a, b) {
  first <- strsplit(a, "", fixed = TRUE)[[1]]
  second <- strsplit(b, "", fixed = TRUE)[[1]]
  if (length(first) != length(second)) {
    stop("mismatch_positions requires strings of equal length")
  }
  which(first != second)
}

similarity_ratio <- function(a, b) {
  width <- nchar(a)
  if (width == 0L) {
    return(1)
  }
  distance <- hamming_distance(a, b)
  1 - distance / width
}

marker_line <- function(a, b) {
  marks <- rep(".", nchar(a))
  spots <- mismatch_positions(a, b)
  marks[spots] <- "^"
  paste(marks, collapse = "")
}

format_report <- function(a, b) {
  distance <- hamming_distance(a, b)
  ratio <- similarity_ratio(a, b)
  spots <- mismatch_positions(a, b)
  where <- if (length(spots) == 0L) "none" else paste(spots, collapse = ", ")
  report <- c(
    sprintf("  %s", a),
    sprintf("  %s", b),
    sprintf("  %s", marker_line(a, b)),
    sprintf("  distance = %d, similarity = %.2f, differing positions: %s",
            distance, ratio, where)
  )
  paste(report, collapse = "\n")
}

main <- function() {
  samples <- list(
    c("karolin", "kathrin"),
    c("abc", "abd"),
    c("1011101", "1001001"),
    c("identical", "identical")
  )
  for (sample in samples) {
    left <- sample[1]
    right <- sample[2]
    cat(sprintf("hamming_distance(\"%s\", \"%s\") = %d\n",
                left, right, hamming_distance(left, right)))
    cat(format_report(left, right), "\n\n", sep = "")
  }
  failure <- tryCatch(hamming_distance("short", "longer"),
                      error = function(e) conditionMessage(e))
  cat("mismatched lengths:", failure, "\n")
}

main()

