generate_permutations <- function(elements) {
  n <- length(elements)

  if (n == 0) {
    return(list(c()))
  }
  if (n == 1) {
    return(list(elements))
  }

  all_permutations <- list()

  for (i in seq_len(n)) {
    first_element <- elements[i]
    remaining_elements <- elements[-i]

    sub_permutations <- generate_permutations(remaining_elements)

    for (sub_perm in sub_permutations) {
      current_permutation <- c(first_element, sub_perm)
      all_permutations <- c(all_permutations, list(current_permutation))
    }
  }

  return(all_permutations)
}

