calculate_dot_product <- function(a, b) {
  validate_vectors(a, b)
  total <- 0
  for (i in seq_along(a)) {
    total <- total + a[i] * b[i]
  }
  total
}

validate_vectors <- function(a, b) {
  if (!is.numeric(a) || !is.numeric(b)) {
    stop("both inputs must be numeric vectors")
  }
  if (length(a) != length(b)) {
    stop("vectors must have the same length")
  }
  if (length(a) == 0) {
    stop("vectors must contain at least one element")
  }
  invisible(TRUE)
}

vector_norm <- function(v) {
  sqrt(calculate_dot_product(v, v))
}

cosine_similarity <- function(a, b) {
  denominator <- vector_norm(a) * vector_norm(b)
  if (denominator == 0) {
    stop("cosine similarity is undefined for a zero vector")
  }
  calculate_dot_product(a, b) / denominator
}

format_vector <- function(v) {
  parts <- formatC(v, format = "g")
  paste0("(", paste(parts, collapse = ", "), ")")
}

describe_pair <- function(a, b) {
  product <- calculate_dot_product(a, b)
  relation <- if (isTRUE(all.equal(product, 0))) {
    "orthogonal"
  } else if (product > 0) {
    "acute angle"
  } else {
    "obtuse angle"
  }
  sprintf(
    "%s . %s = %s  [%s]",
    format_vector(a), format_vector(b), formatC(product, format = "g"), relation
  )
}

main <- function() {
  vector_pairs <- list(
    list(a = c(1, 2, 3), b = c(4, 5, 6)),
    list(a = c(1, 0), b = c(0, 1)),
    list(a = c(-2, 4), b = c(3, 1))
  )
  for (pair in vector_pairs) {
    cat(describe_pair(pair$a, pair$b), "\n")
  }
  first <- vector_pairs[[1]]
  similarity <- cosine_similarity(first$a, first$b)
  cat(sprintf("cosine similarity of first pair: %.6f\n", similarity))
}

main()

