find_second_smallest <- function(x) {
  cleaned <- validate_numeric_vector(x)
  uniques <- unique(cleaned)
  if (length(uniques) < 2L) {
    stop("input must contain at least two unique elements")
  }
  smallest <- min(uniques)
  remaining <- uniques[uniques > smallest]
  min(remaining)
}

validate_numeric_vector <- function(x) {
  if (!is.numeric(x)) {
    stop("input must be a numeric vector")
  }
  cleaned <- x[!is.na(x)]
  if (length(cleaned) < 2L) {
    stop("input must contain at least two non-missing values")
  }
  cleaned
}

rank_two_smallest <- function(x) {
  first <- min(validate_numeric_vector(x))
  second <- find_second_smallest(x)
  c(smallest = first, second_smallest = second)
}

format_vector <- function(x) {
  parts <- format(x, trim = TRUE)
  paste0("c(", paste(parts, collapse = ", "), ")")
}

describe_second_smallest <- function(x) {
  pair <- rank_two_smallest(x)
  label <- format_vector(x)
  sprintf("%s -> smallest = %s, second smallest = %s",
          label,
          format(pair[["smallest"]], trim = TRUE),
          format(pair[["second_smallest"]], trim = TRUE))
}

report <- function(samples) {
  lines <- vapply(samples, describe_second_smallest, character(1))
  paste(lines, collapse = "\n")
}

main <- function() {
  samples <- list(
    c(5, 2, 8, 2, 1),
    c(10, 20, 30),
    c(3, 3, 3, -7, 0, -7),
    c(1.5, NA, 0.25, 1.5)
  )
  cat(report(samples), "\n", sep = "")

  broken <- c(4, 4, 4, 4)
  outcome <- tryCatch(find_second_smallest(broken),
                      error = function(e) conditionMessage(e))
  cat(format_vector(broken), "-> ", outcome, "\n", sep = "")

  invisible(NULL)
}

main()

