is_palindrome_number <- function(x) {
  if (x < 0) {
    return(FALSE)
  }

  original_number <- x
  reversed_number <- 0

  while (x > 0) {
    last_digit <- x %% 10
    reversed_number <- reversed_number * 10 + last_digit
    x <- floor(x / 10)
  }

  is_equal <- original_number == reversed_number
  return(is_equal)
}

test_value1 <- 121
result1 <- is_palindrome_number(test_value1)

test_value2 <- 123
result2 <- is_palindrome_number(test_value2)

test_value3 <- -121
result3 <- is_palindrome_number(test_value3)

test_value4 <- 0
result4 <- is_palindrome_number(test_value4)

test_value5 <- 1
result5 <- is_palindrome_number(test_value5)

print_result <- function(value, expected) {
  actual <- is_palindrome_number(value)
  cat(paste0("is_palindrome_number(", value, ") expected: ", expected, ", got: ", actual, "\n"))
}

output1 <- print_result(121, TRUE)
output2 <- print_result(123, FALSE)
output3 <- print_result(-121, FALSE)
output4 <- print_result(0, TRUE)
output5 <- print_result(1, TRUE)

