extract_digits <- function(text) {
  if (!is.character(text) || length(text) != 1L || is.na(text)) {
    stop("extract_digits() expects a single non-missing character string")
  }
  chars <- strsplit(text, "", fixed = TRUE)[[1]]
  keep <- chars %in% as.character(0:9)
  digits <- chars[keep]
  if (length(digits) == 0L) {
    return(numeric(0))
  }
  as.numeric(digits)
}

digit_sum <- function(text) {
  digits <- extract_digits(text)
  sum(digits)
}

digit_tally <- function(text) {
  digits <- extract_digits(text)
  counts <- integer(10)
  names(counts) <- as.character(0:9)
  for (d in digits) {
    key <- as.character(d)
    counts[key] <- counts[key] + 1L
  }
  counts[counts > 0L]
}

format_digits <- function(text) {
  digits <- extract_digits(text)
  if (length(digits) == 0L) {
    return("(none)")
  }
  paste(digits, collapse = ", ")
}

describe_string <- function(text) {
  listing <- format_digits(text)
  total <- digit_sum(text)
  tally <- digit_tally(text)
  breakdown <- if (length(tally) == 0L) {
    "no digit occurs"
  } else {
    paste(sprintf("%sx%d", names(tally), unname(tally)), collapse = " ")
  }
  sprintf("%-20s -> [%s] sum=%s counts: %s",
          sQuote(text), listing, total, breakdown)
}

main <- function() {
  samples <- c("abc123def45", "no numbers here", "2024-09-18", "a1b2c3")
  report <- vapply(samples, describe_string, character(1), USE.NAMES = FALSE)
  cat(report, sep = "\n")
  cat("\n")
  first <- extract_digits(samples[1])
  stopifnot(identical(first, c(1, 2, 3, 4, 5)))
  empty <- extract_digits(samples[2])
  stopifnot(identical(empty, numeric(0)))
  invisible(report)
}

main()

