validate_columns <- function(df, columns) {
  missing <- setdiff(columns, names(df))
  if (length(missing) > 0L) {
    stop("unknown column(s): ", paste(missing, collapse = ", "))
  }
  invisible(TRUE)
}

match_column <- function(df, column, value) {
  observed <- df[[column]]
  if (is.factor(observed)) {
    observed <- as.character(observed)
  }
  if (is.character(observed)) {
    value <- as.character(value)
  }
  hits <- observed == value
  hits[is.na(hits)] <- FALSE
  hits
}

filter_df_by_conditions <- function(df, col1, val1, col2, val2) {
  if (!is.data.frame(df)) {
    stop("df must be a data frame")
  }
  validate_columns(df, c(col1, col2))
  keep <- match_column(df, col1, val1) & match_column(df, col2, val2)
  result <- df[keep, , drop = FALSE]
  rownames(result) <- NULL
  result
}

describe_filter <- function(col1, val1, col2, val2) {
  first <- paste0(col1, " == ", format(val1))
  second <- paste0(col2, " == ", format(val2))
  paste(first, "AND", second)
}

report_filter <- function(df, col1, val1, col2, val2) {
  subset_df <- filter_df_by_conditions(df, col1, val1, col2, val2)
  header <- describe_filter(col1, val1, col2, val2)
  cat(header, "\n")
  cat("rows kept:", nrow(subset_df), "of", nrow(df), "\n")
  if (nrow(subset_df) == 0L) {
    cat("<no matching rows>\n\n")
  } else {
    print(subset_df)
    cat("\n")
  }
  invisible(subset_df)
}

main <- function() {
  df1 <- data.frame(A = c(1, 2, 3), B = c("x", "y", "x"), stringsAsFactors = FALSE)
  report_filter(df1, "A", 1, "B", "x")

  df2 <- data.frame(ID = c(1, 2), Status = c("Active", "Inactive"), stringsAsFactors = FALSE)
  report_filter(df2, "ID", 2, "Status", "Active")

  sales <- data.frame(
    region = c("north", "south", "north", "north"),
    year = c(2023, 2023, 2024, 2023),
    units = c(10, 7, 12, 4),
    stringsAsFactors = FALSE
  )
  northern <- report_filter(sales, "region", "north", "year", 2023)
  cat("total units:", sum(northern$units), "\n")
}

main()

