validate_inputs <- function(x, threshold) {
  if (!is.numeric(x)) {
    stop("`x` must be a numeric vector")
  }
  if (!is.numeric(threshold) || length(threshold) != 1L) {
    stop("`threshold` must be a single numeric value")
  }
  finite_check <- all(is.finite(x)) && is.finite(threshold)
  if (!finite_check) {
    stop("inputs must be finite numbers")
  }
  invisible(TRUE)
}

all_greater_than <- function(x, threshold) {
  validate_inputs(x, threshold)
  comparisons <- x > threshold
  all(comparisons)
}

offending_values <- function(x, threshold) {
  validate_inputs(x, threshold)
  failed <- x[x <= threshold]
  unique(failed)
}

describe_check <- function(x, threshold) {
  verdict <- all_greater_than(x, threshold)
  vector_text <- paste(format(x, trim = TRUE), collapse = ", ")
  header <- sprintf("c(%s) vs %s -> %s", vector_text, format(threshold), verdict)
  if (verdict) {
    return(header)
  }
  bad <- offending_values(x, threshold)
  detail <- paste(format(bad, trim = TRUE), collapse = ", ")
  paste0(header, " (not greater: ", detail, ")")
}

summarise_cases <- function(cases) {
  report <- character(length(cases))
  for (i in seq_along(cases)) {
    case <- cases[[i]]
    report[i] <- describe_check(case$values, case$threshold)
  }
  report
}

main <- function() {
  cases <- list(
    list(values = c(5, 6, 7), threshold = 4),
    list(values = c(5, 6, 7), threshold = 7),
    list(values = c(-3, 0.5, 12), threshold = -10),
    list(values = c(2, 2, 2), threshold = 2)
  )
  report <- summarise_cases(cases)
  cat(report, sep = "\n")
  cat("\n")
  passed <- sum(vapply(cases, function(case) all_greater_than(case$values, case$threshold), logical(1)))
  cat(sprintf("%d of %d cases satisfied the condition\n", passed, length(cases)))
}

main()

