validate_inputs = function(x, threshold) {
  if (!is.numeric(x)) {
    stop("`x` must be a numeric vector")
  }
  if (!is.numeric(threshold) || length(threshold) != 1L) {
    stop("`threshold` must be a single numeric value")
  }
  finite_check = all(is.finite(x)) && is.finite(threshold)
  if (!finite_check) {
    stop("inputs must be finite numbers")
  }
  invisible(TRUE)
}

all_greater_than = function(x, threshold) {
  validate_inputs(x, threshold)
  comparisons = x > threshold
  all(comparisons)
}

offending_values = function(x, threshold) {
  validate_inputs(x, threshold)
  failed = x[x <= threshold]
  unique(failed)
}

