cylinder_volume <- function(radius, height) {
  if (!is.numeric(radius) || !is.numeric(height)) {
    stop("radius and height must be numeric")
  }
  if (any(radius < 0) || any(height < 0)) {
    stop("radius and height must be non-negative")
  }
  base_area <- pi * radius^2
  base_area * height
}

cylinder_surface_area <- function(radius, height) {
  caps <- 2 * pi * radius^2
  side <- 2 * pi * radius * height
  caps + side
}

format_cylinder <- function(radius, height, digits = 5) {
  volume <- cylinder_volume(radius, height)
  area <- cylinder_surface_area(radius, height)
  sprintf(
    "r = %s, h = %s -> volume = %s, surface = %s",
    format(radius),
    format(height),
    format(round(volume, digits), nsmall = 0),
    format(round(area, digits), nsmall = 0)
  )
}

cylinder_table <- function(radii, heights) {
  grid <- expand.grid(radius = radii, height = heights)
  grid$volume <- cylinder_volume(grid$radius, grid$height)
  grid$surface <- cylinder_surface_area(grid$radius, grid$height)
  grid[order(grid$volume), ]
}

main <- function() {
  examples <- list(c(2, 3), c(1, 1))
  for (pair in examples) {
    line <- format_cylinder(pair[1], pair[2])
    cat(line, "\n")
  }

  radii <- c(0.5, 1, 2)
  heights <- c(1, 4)
  tbl <- cylinder_table(radii, heights)
  cat("\nVolume table (ascending):\n")
  print(tbl, row.names = FALSE, digits = 7)

  largest <- tbl[nrow(tbl), ]
  cat(sprintf(
    "\nLargest volume: %.5f (r = %g, h = %g)\n",
    largest$volume, largest$radius, largest$height
  ))

  total <- sum(tbl$volume)
  cat(sprintf("Combined volume of all %d cylinders: %.5f\n", nrow(tbl), total))
}

if (identical(environment(), globalenv())) {
  main()
}

