simple_matrix_transpose <- function(rows) {
  if (!is.list(rows)) {
    stop("input must be a list of numeric vectors")
  }
  if (length(rows) == 0) {
    return(list())
  }
  widths <- vapply(rows, length, integer(1))
  n_cols <- widths[1]
  if (any(widths != n_cols)) {
    stop("all rows must have the same length")
  }
  result <- vector("list", n_cols)
  for (j in seq_len(n_cols)) {
    column <- vapply(rows, function(row) as.numeric(row[j]), numeric(1))
    result[[j]] <- column
  }
  result
}

format_matrix <- function(rows) {
  if (length(rows) == 0) {
    return("(empty)")
  }
  cells <- lapply(rows, function(row) formatC(row, format = "g", width = 6))
  lines <- vapply(cells, paste, character(1), collapse = " ")
  paste(lines, collapse = "\n")
}

matrix_dimensions <- function(rows) {
  n_rows <- length(rows)
  n_cols <- if (n_rows == 0) 0L else length(rows[[1]])
  c(rows = n_rows, cols = n_cols)
}

report_transpose <- function(rows, label) {
  transposed <- simple_matrix_transpose(rows)
  before <- matrix_dimensions(rows)
  after <- matrix_dimensions(transposed)
  header <- sprintf("%s: %dx%d -> %dx%d", label,
                    before[["rows"]], before[["cols"]],
                    after[["rows"]], after[["cols"]])
  cat(header, "\n", sep = "")
  cat("original:\n", format_matrix(rows), "\n", sep = "")
  cat("transpose:\n", format_matrix(transposed), "\n\n", sep = "")
  invisible(transposed)
}

main <- function() {
  square <- list(c(1, 2), c(3, 4))
  single_row <- list(c(1, 2, 3))
  wide <- list(c(1, 2, 3, 4), c(5, 6, 7, 8), c(9, 10, 11, 12))
  report_transpose(square, "square")
  report_transpose(single_row, "single row")
  round_trip <- simple_matrix_transpose(simple_matrix_transpose(wide))
  report_transpose(wide, "wide")
  cat("round trip identical to original: ",
      identical(round_trip, lapply(wide, as.numeric)), "\n", sep = "")
}

main()

