count_vowel_start_words <- function(text_string) {
  text_lower <- tolower(text_string)
  words_list <- strsplit(text_lower, " ")[[1]]
  vowels_set <- c("a", "e", "i", "o", "u")
  vowel_start_count <- 0

  for (word in words_list) {
    if (nchar(word) > 0) {
      first_char <- substr(word, 1, 1)
      is_vowel_start <- first_char %in% vowels_set
      if (is_vowel_start) {
        vowel_start_count <- vowel_start_count + 1
      }
    }
  }
  return(vowel_start_count)
}

