FNV_PRIME <- 16777619
FNV_OFFSET <- 2166136261

mul32 <- function(a, b) {
  lo <- a %% 65536
  hi <- a %/% 65536
  ((lo * b) %% 4294967296 + ((hi * b) %% 65536) * 65536) %% 4294967296
}

xor_byte <- function(h, byte) {
  lo <- bitwXor(h %% 65536, byte)
  hi <- h %/% 65536
  hi * 65536 + lo
}

fnv1a32 <- function(bytes, offset) {
  h <- offset
  for (b in bytes) {
    h <- xor_byte(h, b)
    h <- mul32(h, FNV_PRIME)
  }
  h
}

hex32 <- function(h) sprintf("%04x%04x", h %/% 65536, h %% 65536)

url_digest <- function(url) {
  bytes <- as.integer(charToRaw(url))
  first <- fnv1a32(bytes, FNV_OFFSET)
  second <- fnv1a32(rev(bytes), mul32(FNV_OFFSET, FNV_PRIME))
  paste0(hex32(first), hex32(second))
}

validate_url <- function(url) {
  if (!is.character(url) || length(url) != 1L || is.na(url)) {
    stop("url must be a single non-missing string")
  }
  trimmed <- trimws(url)
  if (!nzchar(trimmed)) {
    stop("url must not be empty")
  }
  trimmed
}

shorten_url <- function(url) {
  clean <- validate_url(url)
  code <- substr(url_digest(clean), 1, 10)
  paste0("http://short.ly/", code)
}

registry <- new.env(parent = emptyenv())

short_key <- function(short) sub("^http://short\\.ly/", "", short)

register_url <- function(url, store = registry) {
  short <- shorten_url(url)
  assign(short_key(short), validate_url(url), envir = store)
  short
}

expand_url <- function(short, store = registry) {
  key <- short_key(short)
  if (!exists(key, envir = store, inherits = FALSE)) {
    return(NA_character_)
  }
  get(key, envir = store)
}

report <- function(urls) {
  shorts <- vapply(urls, register_url, character(1), USE.NAMES = FALSE)
  restored <- vapply(shorts, expand_url, character(1), USE.NAMES = FALSE)
  data.frame(long = urls, short = shorts, roundtrip = restored == urls,
             stringsAsFactors = FALSE)
}

main <- function() {
  samples <- c("https://www.example.com/very/long/url/path/to/resource",
               "https://www.google.com",
               "https://www.example.com/very/long/url/path/to/resource")
  summary_rows <- report(samples)
  for (i in seq_len(nrow(summary_rows))) {
    line <- sprintf("%-56s -> %s  roundtrip=%s", summary_rows$long[i],
                    summary_rows$short[i], summary_rows$roundtrip[i])
    cat(line, "\n", sep = "")
  }
  distinct <- length(unique(summary_rows$short))
  cat(sprintf("stored codes: %d, distinct short urls: %d\n",
              length(ls(registry)), distinct))
}

main()

