group_vector_elements <- function(vec, n) {
  if (!is.numeric(n) || length(n) != 1L || is.na(n)) {
    stop("n must be a single non-missing number")
  }
  if (n != as.integer(n) || n < 1L) {
    stop("n must be a positive integer")
  }
  size <- as.integer(n)
  total <- length(vec)
  if (total == 0L) {
    return(list())
  }
  starts <- seq.int(1L, total, by = size)
  groups <- lapply(starts, function(from) {
    to <- min(from + size - 1L, total)
    vec[from:to]
  })
  groups
}

group_sizes <- function(groups) {
  vapply(groups, length, integer(1))
}

format_group <- function(group) {
  parts <- if (is.character(group)) sprintf("'%s'", group) else format(group, trim = TRUE)
  paste0("c(", paste(parts, collapse = ", "), ")")
}

format_groups <- function(groups) {
  if (length(groups) == 0L) {
    return("list()")
  }
  rendered <- vapply(groups, format_group, character(1))
  paste0("list(", paste(rendered, collapse = ", "), ")")
}

describe_grouping <- function(vec, n) {
  groups <- group_vector_elements(vec, n)
  sizes <- group_sizes(groups)
  remainder <- length(vec) %% n
  tail_note <- if (remainder == 0L) "all groups full" else sprintf("last group holds %d element(s)", remainder)
  sprintf("%d element(s) -> %d group(s) [%s]; %s\n  %s",
          length(vec), length(groups), paste(sizes, collapse = "+"),
          tail_note, format_groups(groups))
}

main <- function() {
  numbers <- c(1, 2, 3, 4, 5)
  letters4 <- c("a", "b", "c", "d")
  cases <- list(
    list(data = numbers, n = 2),
    list(data = letters4, n = 3),
    list(data = seq_len(9), n = 3),
    list(data = character(0), n = 4)
  )
  for (case in cases) {
    cat(describe_grouping(case$data, case$n), "\n\n", sep = "")
  }
  failure <- tryCatch(group_vector_elements(numbers, 0), error = function(e) conditionMessage(e))
  cat("invalid n rejected:", failure, "\n")
}

main()

