flatten_list <- function(x) {
  if (!is.list(x)) {
    stop("flatten_list expects a list of lists or vectors")
  }
  pieces <- lapply(x, function(part) {
    if (is.list(part)) {
      unlist(part, use.names = FALSE)
    } else {
      part
    }
  })
  result <- unlist(pieces, use.names = FALSE)
  if (is.null(result)) {
    result <- logical(0)
  }
  result
}

depth_of <- function(x) {
  if (!is.list(x)) {
    return(0L)
  }
  if (length(x) == 0L) {
    return(1L)
  }
  inner <- vapply(x, depth_of, integer(1))
  1L + max(inner)
}

describe_flat <- function(x) {
  flat <- flatten_list(x)
  kind <- class(flat)[1]
  parts <- length(x)
  report <- sprintf("%d group(s), depth %d -> %d element(s) of type %s",
                    parts, depth_of(x), length(flat), kind)
  list(values = flat, report = report)
}

format_values <- function(values) {
  if (length(values) == 0L) {
    return("<empty>")
  }
  shown <- if (is.character(values)) {
    paste0("'", values, "'")
  } else {
    format(values, trim = TRUE)
  }
  paste(shown, collapse = ", ")
}

main <- function() {
  cases <- list(
    numbers = list(list(1, 2), list(3, 4)),
    letters = list(list("a", "b"), list("c")),
    mixed_vectors = list(c(10, 20), list(30), c(40, 50, 60)),
    nested = list(list(1, list(2, 3)), list(4)),
    empty = list()
  )
  for (name in names(cases)) {
    info <- describe_flat(cases[[name]])
    line <- paste0(name, ": ", format_values(info$values))
    cat(line, "\n", sep = "")
    cat("  ", info$report, "\n", sep = "")
  }
  invisible(NULL)
}

main()

