calculate_factorial <- function(n) {
  validate_input(n)
  result <- 1
  if (n > 1) {
    for (k in 2:n) {
      result <- result * k
    }
  }
  result
}

validate_input <- function(n) {
  if (length(n) != 1L) {
    stop("calculate_factorial expects a single value")
  }
  if (!is.numeric(n) || is.na(n)) {
    stop("calculate_factorial expects a numeric, non-missing value")
  }
  if (n != floor(n)) {
    stop("calculate_factorial expects a whole number")
  }
  if (n < 0) {
    stop("calculate_factorial expects a non-negative integer")
  }
  invisible(TRUE)
}

factorial_digits <- function(n) {
  value <- calculate_factorial(n)
  if (value < .Machine$double.xmax) {
    digits <- nchar(format(value, scientific = FALSE))
  } else {
    digits <- NA_integer_
  }
  as.integer(digits)
}

format_factorial <- function(n) {
  value <- calculate_factorial(n)
  shown <- format(value, scientific = FALSE, big.mark = ",")
  sprintf("%d! = %s", as.integer(n), shown)
}

factorial_table <- function(ns) {
  rows <- vapply(ns, format_factorial, character(1))
  paste(rows, collapse = "\n")
}

safe_factorial <- function(n) {
  outcome <- tryCatch(
    calculate_factorial(n),
    error = function(e) {
      message("skipping input: ", conditionMessage(e))
      NA_real_
    }
  )
  outcome
}

main <- function() {
  small <- c(0, 1, 5, 10)
  cat(factorial_table(small), "\n", sep = "")

  twenty <- calculate_factorial(20)
  cat("20! is", format(twenty, scientific = FALSE), "\n")
  cat("20! has", factorial_digits(20), "digits\n")

  bad <- list(-3, 2.5, "seven")
  cleaned <- vapply(bad, safe_factorial, numeric(1))
  cat("rejected inputs produced:", sum(is.na(cleaned)), "NA values\n")
}

if (identical(environment(), globalenv())) {
  main()
}

