remove_punctuation <- function(text) {
  if (!is.character(text)) {
    stop("remove_punctuation() expects a character vector")
  }
  pattern <- "[[:punct:]]"
  gsub(pattern, "", text)
}

count_punctuation <- function(text) {
  matches <- gregexpr("[[:punct:]]", text)
  vapply(matches, function(m) {
    found <- as.integer(m)
    if (identical(found, -1L)) 0L else length(found)
  }, integer(1))
}

punctuation_profile <- function(text) {
  matches <- regmatches(text, gregexpr("[[:punct:]]", text))
  chars <- unlist(matches, use.names = FALSE)
  if (length(chars) == 0L) {
    return(character(0))
  }
  tally <- table(chars)
  ordered <- sort(tally, decreasing = TRUE)
  labels <- paste0(names(ordered), " x", as.integer(ordered))
  labels
}

clean_report <- function(text) {
  cleaned <- remove_punctuation(text)
  removed <- count_punctuation(text)
  data.frame(
    original = text,
    cleaned = cleaned,
    removed = removed,
    stringsAsFactors = FALSE
  )
}

format_report <- function(report) {
  lines <- character(nrow(report))
  for (i in seq_len(nrow(report))) {
    row <- report[i, ]
    noun <- if (row$removed == 1L) "mark" else "marks"
    lines[i] <- sprintf("%-24s -> %-24s (%d %s)",
                        row$original, row$cleaned, row$removed, noun)
  }
  paste(lines, collapse = "\n")
}

main <- function() {
  samples <- c("Hello, world!", "R is fun.", "Well... maybe; perhaps?",
               "no punctuation here")
  report <- clean_report(samples)
  cat(format_report(report), "\n", sep = "")

  profile <- punctuation_profile(samples)
  summary_line <- if (length(profile) == 0L) {
    "no punctuation found"
  } else {
    paste(profile, collapse = ", ")
  }
  cat("Punctuation seen: ", summary_line, "\n", sep = "")

  total <- sum(report$removed)
  cat("Total characters removed: ", total, "\n", sep = "")
}

main()

