reverse_vector <- function(vec) {
  n <- length(vec)
  if (n <= 1L) {
    return(vec)
  }
  idx <- seq.int(from = n, to = 1L, by = -1L)
  vec[idx]
}

reverse_in_chunks <- function(vec, size) {
  if (size < 1L) {
    stop("chunk size must be at least 1")
  }
  n <- length(vec)
  groups <- ((seq_len(n) - 1L) %/% size)
  pieces <- split(vec, groups)
  reversed <- lapply(pieces, reverse_vector)
  unlist(reversed, use.names = FALSE)
}

is_palindromic <- function(vec) {
  flipped <- reverse_vector(vec)
  identical(as.character(vec), as.character(flipped))
}

describe_reversal <- function(vec, label) {
  original <- paste(format(vec, trim = TRUE), collapse = " ")
  flipped <- paste(format(reverse_vector(vec), trim = TRUE), collapse = " ")
  marker <- if (is_palindromic(vec)) " (palindromic)" else ""
  sprintf("%-12s [%s] -> [%s]%s", label, original, flipped, marker)
}

main <- function() {
  numbers <- c(1, 2, 3)
  letters_pair <- c("a", "b")
  flags <- c(TRUE, FALSE, TRUE)
  single <- 42
  empty <- character(0)

  cases <- list(
    numeric = numbers,
    character = letters_pair,
    logical = flags,
    singleton = single,
    empty = empty
  )

  report <- vapply(
    names(cases),
    function(nm) describe_reversal(cases[[nm]], nm),
    character(1)
  )
  cat(report, sep = "\n")
  cat("\n")

  long <- seq_len(10L)
  chunked <- reverse_in_chunks(long, 3L)
  cat(sprintf(
    "chunks of 3   [%s] -> [%s]\n",
    paste(long, collapse = " "),
    paste(chunked, collapse = " ")
  ))

  word <- strsplit("racecar", "")[[1]]
  cat(sprintf(
    "word          %s reads %s\n",
    paste(word, collapse = ""),
    paste(reverse_vector(word), collapse = "")
  ))

  invisible(report)
}

main()

