convert_string_case <- function(s, case) {
  if (!is.character(s) || length(s) != 1L || is.na(s)) {
    stop("'s' must be a single non-missing character string")
  }
  if (!is.character(case) || length(case) != 1L || is.na(case)) {
    stop("'case' must be a single non-missing character string")
  }
  target <- tolower(trimws(case))
  if (target == "upper") {
    result <- toupper(s)
  } else if (target == "lower") {
    result <- tolower(s)
  } else {
    stop("'case' must be either 'upper' or 'lower'")
  }
  result
}

convert_many <- function(strings, case) {
  vapply(strings, convert_string_case, character(1), case = case,
         USE.NAMES = FALSE)
}

describe_conversion <- function(s, case) {
  converted <- convert_string_case(s, case)
  status <- if (identical(converted, s)) "unchanged" else "changed"
  sprintf("%-14s -> %-14s [%s, %s]", s, converted, tolower(trimws(case)), status)
}

safe_convert <- function(s, case) {
  tryCatch(convert_string_case(s, case),
           error = function(e) paste("error:", conditionMessage(e)))
}

main <- function() {
  samples <- c("Hello", "WORLD", "MiXeD cAsE", "already upper")
  upper_forms <- convert_many(samples, "upper")
  lower_forms <- convert_many(samples, "lower")

  cat("Upper:", paste(upper_forms, collapse = " | "), "\n")
  cat("Lower:", paste(lower_forms, collapse = " | "), "\n\n")

  report <- vapply(samples, describe_conversion, character(1), case = "upper",
                   USE.NAMES = FALSE)
  cat(paste(report, collapse = "\n"), "\n\n")

  bad_cases <- list(list("Hello", "title"), list(42, "upper"), list("Hi", NA_character_))
  for (attempt in bad_cases) {
    outcome <- safe_convert(attempt[[1]], attempt[[2]])
    cat(outcome, "\n")
  }
}

main()

