remove_na <- function(x) {
  if (is.null(x)) {
    return(x)
  }
  keep <- !is.na(x)
  x[keep]
}

count_na <- function(x) {
  if (is.null(x)) {
    return(0L)
  }
  sum(is.na(x))
}

na_positions <- function(x) {
  flags <- is.na(x)
  which(flags)
}

describe_vector <- function(x, label) {
  total <- length(x)
  missing <- count_na(x)
  kept <- total - missing
  type <- class(x)[1]
  sprintf("%-10s type=%-9s length=%2d kept=%2d removed=%2d",
          label, type, total, kept, missing)
}

format_vector <- function(x) {
  if (length(x) == 0) {
    return("<empty>")
  }
  shown <- ifelse(is.na(x), "NA", as.character(x))
  paste(shown, collapse = ", ")
}

clean_columns <- function(df) {
  cleaned <- lapply(df, remove_na)
  names(cleaned) <- names(df)
  cleaned
}

report <- function(samples) {
  labels <- names(samples)
  for (i in seq_along(samples)) {
    original <- samples[[i]]
    stripped <- remove_na(original)
    positions <- na_positions(original)
    where <- if (length(positions) == 0) "none" else paste(positions, collapse = "/")
    cat(describe_vector(original, labels[i]), "\n")
    cat("  before :", format_vector(original), "\n")
    cat("  after  :", format_vector(stripped), "\n")
    cat("  na at  :", where, "\n")
  }
  invisible(NULL)
}

main <- function() {
  numbers <- c(1, NA, 2, NA, 3)
  letters_in <- c('a', NA, 'b')
  flags <- c(TRUE, NA, FALSE, NA)
  all_missing <- c(NA, NA)
  samples <- list(numbers = numbers, letters = letters_in,
                  flags = flags, empty = all_missing)
  report(samples)

  frame <- data.frame(score = c(10, NA, 30), grade = c('A', 'B', NA),
                      stringsAsFactors = FALSE)
  tidy <- clean_columns(frame)
  cat("data frame columns after cleaning:\n")
  for (nm in names(tidy)) {
    cat(" ", nm, "->", format_vector(tidy[[nm]]), "\n")
  }
}

main()

